#include "xge.h"
#include <stdio.h>
#include <string.h>
#include <math.h>
static int checks,failures;
#define CHECK(x) do{++checks;if(!(x)){++failures;fprintf(stderr,"LOCAL %d: %s\n",__LINE__,#x);}}while(0)
int main(void){xge3d_scene *scene=NULL;CHECK(!xge3dSceneCreate(&scene));xge3d_node_t root,child;CHECK(!xge3dNodeCreate(scene,(xge3d_node_t){0},&root)&&!xge3dNodeCreate(scene,root,&child));xge3d_transform_t at=XGE3D_TRANSFORM_IDENTITY;at.position=(xge3d_vec3_t){10,20,30};CHECK(!xge3dNodeSetTransform(scene,root,&at));at.position=(xge3d_vec3_t){1,2,3};at.scale=(xge3d_vec3_t){2,3,4};xge3d_mat4_t expected,local,world;CHECK(!xge3dTransformMatrix(&at,&expected)&&!xge3dNodeSetTransform(scene,child,&at));CHECK(!xge3dNodeGetLocalMatrix(scene,child,&local)&&!memcmp(&local,&expected,sizeof(local)));CHECK(!xge3dNodeGetWorldMatrix(scene,child,&world)&&fabsf(world.m[12]-11)<1e-6f&&fabsf(world.m[13]-22)<1e-6f&&fabsf(world.m[14]-33)<1e-6f);
    expected.m[4]=.75f;CHECK(!xge3dNodeSetMatrix(scene,child,&expected)&&!xge3dNodeGetLocalMatrix(scene,child,&local)&&!memcmp(&local,&expected,sizeof(local)));xge3d_mat4_t unchanged=local;CHECK(xge3dNodeGetLocalMatrix(scene,(xge3d_node_t){0},&local)<0&&!memcmp(&local,&unchanged,sizeof(local)));CHECK(!xge3dNodeSetGlobalPosition(scene,root,(xge3d_dvec3_t){1e9,0,-1e9})&&!xge3dSceneSetOrigin(scene,(xge3d_dvec3_t){1e9,0,-1e9})&&!xge3dNodeGetLocalMatrix(scene,root,&local)&&fabsf(local.m[12])+fabsf(local.m[14])<1e-6f);CHECK(!xge3dNodeGetLocalMatrix(scene,child,&local)&&!memcmp(&local,&expected,sizeof(local)));CHECK(!xge3dNodeDestroy(scene,child));unchanged=local;CHECK(xge3dNodeGetLocalMatrix(scene,child,&local)<0&&!memcmp(&local,&unchanged,sizeof(local)));xge3dSceneFree(scene);printf("Local matrix: %d checks, %d failures; hierarchy, affine rest pose, origin rebase and stale output guard\n",checks,failures);return failures?1:0;}
